    [chr(c) for c in range(ord('A'), ord('Z')+1)] +
    [chr(c) for c in range(ord('a'), ord('z')+1)] + ['_']
)
_XML_NAME_CHAR_EXTRA = ['-', '.', ':']
_XML_DIGITS = [chr(c) for c in range(ord('0'), ord('9')+1)]

