    return s

def _safe_text(r: random.Random, min_len=0, max_len=64) -> str:
    n = r.randint(min_len, max_len)
    return ''.join(_rand(r, SAFE_TEXT_CHARS) for _ in range(n)).strip()

def _attr_value(r: random.Random) -> str:
    # Restrict to ASCII and escape required characters
    base = _safe_text(r, 0, 24)
    return base.replace("&", "&amp;").replace("\"", "&quot;").replace("<", "&lt;")

def _element(r: random.Random, name: str, attrs: List[Tuple[str,str]] = None, children: List[str] = None, text: str | None = None, self_close_ok=True) -> str:
    attrs = attrs or []
    children = children or []
    attr_str = ''.join(f' {k}="{v}"' for k,v in attrs)
    if not children and (text is None or text == "") and self_close_ok:
        return f"<{name}{attr_str}/>"
    inner = ''
    if text is not None:
        # Escape special chars in text
        t = text.replace("&", "&amp;").replace("<", "&lt;")
        inner += t
    inner += ''.join(children)
    return f"<{name}{attr_str}>{inner}</{name}>"

def _maybe_comment(r: random.Random) -> str:
    if r.random() < 0.4:
        body = _safe_text(r, 0, 24).replace("--", "-")
        return f"<!--{body}-->"
    return ""

def _maybe_pi(r: random.Random) -> str:
    if r.random() < 0.25:
        target = _xml_name(r, 8)
        data = _safe_text(r, 0, 24).replace("?", " ")
        return f"<?{target} {data}?>"
    return ""

def _cdata(r: random.Random) -> str:
    if r.random() < 0.35:
        data = _safe_text(r, 0, 48).replace("]]>", "] ]>")
        return f"<![CDATA[{data}]]>"
    return ""

def _doc_decl(r: random.Random) -> str:
    enc = _rand(r, ["UTF-8", "utf-8", "US-ASCII"]) if r.random() < 0.5 else None
    standalone = _rand(r, ["yes", "no"]) if r.random() < 0.5 else None
    parts = ["<?xml version=\"1.0\""]
    if enc:
        parts.append(f" encoding=\"{enc}\"")
    if standalone:
        parts.append(f" standalone=\"{standalone}\"")
    parts.append("?>")
    return ''.join(parts)

def _build_simple_tree(r: random.Random) -> str:
    root = _xml_name(r)
    # optional namespaces
    ns_decls = []
    used_ns = []
    for prefix, uri in NS_CANDIDATES:
        if r.random() < 0.3:
            ns_decls.append((f"xmlns:{prefix}", uri))
            used_ns.append(prefix)
    attrs = []
    # Some attributes
    for _ in range(r.randint(0, 4)):
        an = _xml_name(r)
        av = _attr_value(r)
        attrs.append((an, av))
    # Add namespace declarations to root attrs
    attrs = ns_decls + attrs

    children = []
    # Mix of text, cdata, nested elements
    if r.random() < 0.6:
        children.append(_maybe_comment(r))
    if r.random() < 0.6:
        children.append(_maybe_pi(r))

    for _ in range(r.randint(1, 4)):
        tag = _xml_name(r)
        if used_ns and r.random() < 0.5:
            tag = f"{_rand(r, used_ns)}:{tag}"
        ch_attrs = []
        for _a in range(r.randint(0, 3)):
            ch_attrs.append((_xml_name(r), _attr_value(r)))
        if r.random() < 0.4:
            # Leaf with text/cdata
            t = _safe_text(r, 0, 32)
            node = _element(r, tag, ch_attrs, text=t)
        else:
            # Nested children
            grand = []
            for _b in range(r.randint(0, 3)):
                gname = _xml_name(r)
                if r.random() < 0.3:
                    grand.append(_cdata(r))
                grand.append(_element(r, gname, [("id", _attr_value(r))], text=_safe_text(r, 0, 24)))
            node = _element(r, tag, ch_attrs, children=grand)
        children.append(node)

    # Optional empty element
    if r.random() < 0.5:
        children.append(_element(r, _xml_name(r), [("empty", "true")], children=[], self_close_ok=True))

    body = ''.join(x for x in children if x)
    return _doc_decl(r) + _element(r, root, attrs, children=[body])

def _build_propertyset(r: random.Random) -> str:
    # UPnP event propertyset envelope as used by Notify/AcceptSubscription
    var, vals = _rand(r, UPNP_STATE_VARS)
    val = _rand(r, vals) if r.random() < 0.7 else _safe_text(r, 0, 32)
    inner = f"<e:property><{var}>{val}</{var}></e:property>"
    return (
        _doc_decl(r) +
        f"<e:propertyset xmlns:e=\"urn:schemas-upnp-org:event-1-0\">{inner}</e:propertyset>"
    )

def _build_soap_envelope(r: random.Random) -> str:
    # Minimal SOAP 1.1 envelope with empty action element
    prefix_s, ns_s = "s", "http://schemas.xmlsoap.org/soap/envelope/"
    prefix_u = "u"
    stype = _rand(r, [
        "urn:schemas-upnp-org:service:SwitchPower:1",
        "urn:schemas-upnp-org:service:ContentDirectory:1",
        "urn:schemas-upnp-org:service:RenderingControl:1",
    ])
    act, args = _rand(r, SOAP_ACTIONS)
    # Optionally add an argument
    if r.random() < 0.7 and args:
        argn, argv = _rand(r, args)
        arg = _element(r, argn, text=argv)
        body_inner = f"<{prefix_u}:{act} xmlns:{prefix_u}=\"{stype}\">{arg}</{prefix_u}:{act}>"
    else:
        body_inner = f"<{prefix_u}:{act} xmlns:{prefix_u}=\"{stype}\"></{prefix_u}:{act}>"

    header = ""
    if r.random() < 0.4:
        header = f"<{prefix_s}:Header></{prefix_s}:Header>"
    body = f"<{prefix_s}:Body>{body_inner}</{prefix_s}:Body>"

    return (
        _doc_decl(r) +
        f"<{prefix_s}:Envelope xmlns:{prefix_s}=\"{ns_s}\" {prefix_s}:encodingStyle=\"http://schemas.xmlsoap.org/soap/encoding/\">"+
        header + body + f"</{prefix_s}:Envelope>"
    )

def _ensure_limit(data: str, limit: int = 4096) -> str:
    if len(data) <= limit - 1:  # leave room for NUL if needed by C
        return data
    # try trimming from the end on element/text boundaries by removing trailing content
    return data[:limit-1]

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a template weighted to exercise various paths
    choice = r.random()
    if choice < 0.34:
        xml = _build_simple_tree(r)
    elif choice < 0.67:
        xml = _build_propertyset(r)
    else:
        xml = _build_soap_envelope(r)

    xml = _ensure_limit(xml, 4096)
    # Ensure trailing newline to be friendly to parsers; NUL termination is implicit in C via std::string.c_str()
    if not xml.endswith("\n"):
        xml += "\n"
    return xml.encode("utf-8")

import random
import string
from typing import List

# Generator for valid URL strings suitable for UPnP/libupnp client APIs used in the fuzz stubs.
# Goals:
# - Produce syntactically valid, null-terminated C strings (the harness will treat the buffer as bytes)
# - Cover various schemes and shapes used by the target functions:
#   * HTTP/HTTPS absolute URLs
#   * HTTP with IPv4, IPv6 literals, hostnames, ports
#   * Paths relevant to SOAP control endpoints (e.g., /control, /event, /service)
#   * Query parameters and fragments
#   * GENA event URLs and XML/device description URLs
# - Keep length <= 4096 bytes
# - Deterministic with seed, but varied across calls
#
# The fuzz stubs call FUZZ_PARAM_STR() for:
#   - actionUrl, serviceType (as namespace URL), publisherUrl, general URLs, proxy URLs
# For serviceType (a namespace), a URL-like string such as "urn:schemas-upnp-org:service:...:x" or
# "http://schemas.xmlsoap.org/soap/envelope/" is appropriate. We mix in both HTTP/HTTPS and URN forms.

SAFE = string.ascii_letters + string.digits
LABEL_CHARS = SAFE + "-"
PATH_CHARS = SAFE + "-._~/"
QUERY_CHARS = SAFE + "-._~&=,%+;:@/"
FRAG_CHARS = SAFE + "-._~:@/?"

UPNP_SERVICE_URNS = [
    "urn:schemas-upnp-org:service:ContentDirectory:1",
    "urn:schemas-upnp-org:service:ConnectionManager:1",
    "urn:schemas-upnp-org:service:AVTransport:1",
    "urn:schemas-upnp-org:service:RenderingControl:1",
    "urn:schemas-upnp-org:service:WANIPConnection:1",
    "urn:schemas-upnp-org:device:MediaServer:1",
]

SOAP_NS_URLS = [
    "http://schemas.xmlsoap.org/soap/envelope/",
    "http://schemas.xmlsoap.org/soap/encoding/",
]

CONTROL_PATHS = [
    "/upnp/control", "/ctl", "/control", "/upnp/control/AVTransport1",
    "/upnp/event", "/event", "/upnp/event/RenderingControl1",
    "/rootDesc.xml", "/device.xml", "/service/ContentDirectory1/control",
]

USER_AGENTS = [
    "UPnP/1.1 fuzzer",
    "CyberLink/1.0",
    "libupnp/1.14",
]

DOMAINS = [
    "example.com", "localhost", "test.local", "upnp.lan",
]

PROXIES = [
    "http://proxy.local:8080", "http://127.0.0.1:3128", "http://[::1]:3128",
]

# Helper: random label per RFC-like hostname constraints

def rand_label(r: random.Random, min_len=1, max_len=10) -> str:
    n = r.randint(min_len, max_len)
    # ensure label doesn't start or end with '-'
    s = ''.join(r.choice(LABEL_CHARS) for _ in range(n))
    if s[0] == '-':
        s = 'a' + s[1:]
    if s[-1] == '-':
        s = s[:-1] + 'z'
    return s


def rand_hostname(r: random.Random) -> str:
    if r.random() < 0.4:
        return r.choice(DOMAINS)
    parts = [rand_label(r) for _ in range(r.randint(2, 4))]
    return '.'.join(parts)


def rand_ipv4(r: random.Random) -> str:
    return '.'.join(str(r.randint(1, 223 if i == 0 else 254)) for i in range(4))


def rand_ipv6(r: random.Random) -> str:
    # Simple full form or compressed loopback/site-local variants
    if r.random() < 0.5:
        # full 8 groups
        groups = [format(r.getrandbits(16), 'x') for _ in range(8)]
        return ':'.join(groups)
    else:
        # common literals
        return r.choice(["::1", "fe80::1", "2001:db8::1", "fd00::abcd"])


def rand_path(r: random.Random) -> str:
    if r.random() < 0.5:
        return r.choice(CONTROL_PATHS)
    segs = []
    for _ in range(r.randint(1, 4)):
        seg_len = r.randint(1, 12)
        seg = ''.join(r.choice(PATH_CHARS) for _ in range(seg_len)).strip('/')
        segs.append(seg or 'x')
    return '/' + '/'.join(segs)


def rand_query(r: random.Random) -> str:
    if r.random() < 0.5:
        return ''
    params = []
    for _ in range(r.randint(1, 4)):
        k = ''.join(r.choice(SAFE) for _ in range(r.randint(1, 8)))
        v = ''.join(r.choice(QUERY_CHARS) for _ in range(r.randint(0, 10)))
        params.append(f"{k}={v}")
    return '?' + '&'.join(params)


def rand_fragment(r: random.Random) -> str:
    if r.random() < 0.4:
        return ''
    frag = ''.join(r.choice(FRAG_CHARS) for _ in range(r.randint(1, 12)))
    return '#' + frag


def build_http_url(r: random.Random) -> str:
    scheme = r.choice(["http", "https"])
    # host may be hostname, IPv4 or IPv6 literal
    host_choice = r.random()
    if host_choice < 0.45:
        host = rand_hostname(r)
    elif host_choice < 0.75:
        host = rand_ipv4(r)
    else:
        host = f"[{rand_ipv6(r)}]"
    port = ''
    if r.random() < 0.5:
        p = r.choice([80, 443, 1900, 49152, r.randint(1024, 65535)])
        port = f":{p}"
    path = rand_path(r)
    query = rand_query(r)
    frag = rand_fragment(r)
    return f"{scheme}://{host}{port}{path}{query}{frag}"


def build_proxy_url(r: random.Random) -> str:
    # For proxy parameters; still a valid http URL
    if r.random() < 0.5:
        return r.choice(PROXIES)
    return build_http_url(r)


def build_service_type_url(r: random.Random) -> str:
    # Mix of URN service types and HTTP namespace URLs
    if r.random() < 0.6:
        # Possibly tweak version number
        base = r.choice(UPNP_SERVICE_URNS)
        if r.random() < 0.4:
            # bump or change version
            try:
                head, ver = base.rsplit(':', 1)
                new_ver = str(max(1, int(ver) + r.randint(-0, 2)))
                return f"{head}:{new_ver}"
            except Exception:
                return base
        return base
    else:
        return r.choice(SOAP_NS_URLS)


def build_generic_url(r: random.Random) -> str:
    # For general URL usages: prefer http(s), but sometimes return a service-type URL
    roll = r.random()
    if roll < 0.8:
        return build_http_url(r)
    elif roll < 0.95:
        return build_proxy_url(r)
    else:
        return build_service_type_url(r)


def choose_role(r: random.Random) -> str:
    # Role indicates which FUZZ_PARAM_STR consumer we're targeting;
    # this lets us tailor strings for serviceType vs URL vs proxy.
    return r.choice([
        "action_url", "service_type", "publisher_url", "generic_url", "proxy_url",
    ])


def make_string_for_role(r: random.Random, role: str) -> str:
    if role == "service_type":
        return build_service_type_url(r)
    elif role == "proxy_url":
        return build_proxy_url(r)
    else:
        # action_url, publisher_url, generic_url all valid HTTP URLs
        return build_http_url(r)


def assemble_multi_payload(r: random.Random) -> bytes:
    # Some stubs call FUZZ_PARAM_STR multiple times per test case. To seed the harness with
    # multiple pre-generated strings, we concatenate NUL-terminated strings back-to-back.
    # Many fuzzers split or reuse slices; this makes several options available in one buffer.
    parts: List[str] = []
    # Always include a solid service type and a couple of HTTP endpoints
    roles = ["service_type", "action_url", "publisher_url", "proxy_url", "generic_url"]
    r.shuffle(roles)
    for role in roles:
        s = make_string_for_role(r, role)
        parts.append(s)
    # Add a few extras with typical control/event paths
    extras = [
        "http://localhost:1400/MediaRenderer/AVTransport/Control",
        "http://127.0.0.1:49152/rootDesc.xml",
        "http://[::1]/upnp/event",
        r.choice(SOAP_NS_URLS),
    ]
    parts.extend(extras)

    # Optionally append query variations
    for _ in range(r.randint(0, 2)):
        parts.append(build_http_url(r))

    # Join as NUL-terminated C strings, and ensure total size <= 4096
    out = bytearray()
    for s in parts:
        b = s.encode('utf-8', errors='strict') + b"\x00"
        if len(out) + len(b) > 4096:
            break
        out += b
    # Ensure at least one string present
    if not out:
        out = bytearray(b"http://localhost/\x00")
    return bytes(out)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # With some probability, return a single targeted URL (useful for harnesses that take one string)
    if r.random() < 0.3:
        role = choose_role(r)
        s = make_string_for_role(r, role)
        return (s + "\x00").encode('utf-8')
    # Otherwise, provide a bundle of multiple NUL-terminated strings
    return assemble_multi_payload(r)
